import json, sys
raw = sys.stdin.read()
d = json.loads(raw)
conns = d.get('Data', [])
print(f'Data type: {type(conns)}')
if isinstance(conns, list):
    for c in conns:
        if isinstance(c, dict):
            print(f'  Id={c.get(\"Id\")} Name={c.get(\"Name\")} State={c.get(\"State\")} IsDefault={c.get(\"IsDefault\")} FolderKey={c.get(\"FolderKey\")}')
        else:
            print('  item:', repr(c))
elif isinstance(conns, dict):
    print('conns keys:', list(conns.keys()))
"

